begin;
create extension if not exists pgtap with schema extensions;
select plan(12);

select ok((select not rolcanlogin and not rolbypassrls from pg_catalog.pg_roles where rolname='offline_pos_writer'),'offline writer is non-login and does not bypass RLS');
select is((select count(*) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace join pg_catalog.pg_roles r on r.oid=p.proowner where n.nspname='offline_pos_private' and p.prosecdef and p.proconfig @> array['search_path=""'] and r.rolname='offline_pos_writer'),19::bigint,'all nineteen offline business functions (incl. intent ingestion, opt-in read, the two adjudication handlers, admin verifier issuance/assertion, offline customers, and the sale reconciliation hold + its ordinal guard/lock) are hardened and writer-owned');
select ok((select bool_and(relrowsecurity and not relforcerowsecurity) from pg_catalog.pg_class where oid in ('public.offline_pos_policies'::regclass,'public.device_credentials'::regclass,'public.offline_device_management_commands'::regclass,'public.offline_grants'::regclass,'public.offline_sale_ingestions'::regclass,'public.offline_reconciliations'::regclass,'public.offline_reconciliation_events'::regclass,'public.offline_attendance_ingestions'::regclass,'public.offline_return_grants'::regclass,'public.offline_return_ingestions'::regclass,'public.offline_return_reconciliations'::regclass,'public.offline_return_reconciliation_events'::regclass,'public.offline_operation_intents'::regclass,'public.offline_pos_admin_verifier_issuances'::regclass,'public.offline_pos_admin_assertions'::regclass,'public.offline_customer_ingestions'::regclass,'public.offline_sale_reconciliation_holds'::regclass)),'all offline tables enable non-forced RLS');
select is((select count(*) from pg_catalog.pg_policies where schemaname='public' and tablename in ('offline_pos_policies','device_credentials','offline_device_management_commands','offline_grants','offline_sale_ingestions','offline_reconciliations','offline_reconciliation_events','offline_attendance_ingestions','offline_return_grants','offline_return_ingestions','offline_return_reconciliations','offline_return_reconciliation_events','offline_operation_intents','offline_pos_admin_verifier_issuances','offline_pos_admin_assertions','offline_customer_ingestions','offline_sale_reconciliation_holds') and roles && array['anon','authenticated']::name[]),0::bigint,'offline tables have no client policies');
select ok((select bool_and(not has_table_privilege('anon',format('public.%I',name),'SELECT') and not has_table_privilege('authenticated',format('public.%I',name),'SELECT')) from unnest(array['offline_pos_policies','device_credentials','offline_device_management_commands','offline_grants','offline_sale_ingestions','offline_reconciliations','offline_reconciliation_events','offline_attendance_ingestions','offline_return_grants','offline_return_ingestions','offline_return_reconciliations','offline_return_reconciliation_events','offline_operation_intents','offline_pos_admin_verifier_issuances','offline_pos_admin_assertions','offline_customer_ingestions']) name),'client roles cannot read offline authority or events');
select ok((select bool_and(has_table_privilege('service_role',format('public.%I',name),'SELECT')) from unnest(array['offline_pos_policies','device_credentials','offline_device_management_commands','offline_grants','offline_sale_ingestions','offline_reconciliations','offline_reconciliation_events','offline_attendance_ingestions','offline_return_grants','offline_return_ingestions','offline_return_reconciliations','offline_return_reconciliation_events','offline_operation_intents','offline_pos_admin_verifier_issuances','offline_pos_admin_assertions','offline_customer_ingestions']) name),'service role may read repository tables');
select ok((select bool_and(not has_table_privilege('service_role',format('public.%I',name),'INSERT') and not has_table_privilege('service_role',format('public.%I',name),'UPDATE') and not has_table_privilege('service_role',format('public.%I',name),'DELETE')) from unnest(array['device_credentials','offline_device_management_commands','offline_grants','offline_sale_ingestions','offline_reconciliations','offline_reconciliation_events','offline_attendance_ingestions','offline_return_grants','offline_return_ingestions','offline_return_reconciliations','offline_return_reconciliation_events','offline_operation_intents','offline_pos_admin_verifier_issuances','offline_pos_admin_assertions','offline_customer_ingestions']) name),'service role cannot mutate offline records directly');
-- Client roles can execute nothing in offline_pos_private; service_role keeps every live entry point.
-- Internal helpers/triggers and the ADR-042 §13 retired paths (issue_return_grant, record_offline_return,
-- revoked in 20261115150000) are executable by no API role.
select ok((select bool_and(not has_function_privilege('anon',p.oid,'EXECUTE') and not has_function_privilege('authenticated',p.oid,'EXECUTE') and not has_function_privilege('public',p.oid,'EXECUTE') and (has_function_privilege('service_role',p.oid,'EXECUTE') = (p.proname in ('enroll_device','enroll_offline_pin','get_intent_operations','issue_grant','offline_pin_authorizations','record_admin_verifier_issuances','record_offline_attendance','record_offline_conflict','record_offline_customer','record_offline_customer_payment','record_offline_intent','record_offline_sale','record_offline_sale_hold','revoke_device','revoke_offline_pin_enrollments','rotate_credential')))) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='offline_pos_private'),'only service role can call offline business entry points');
select ok((select bool_and(not has_function_privilege('service_role',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE') and not has_function_privilege('authenticated',p.oid,'EXECUTE')) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='offline_pos_private' and p.proname in ('offline_sale_ordinal_lock','guard_offline_sale_ordinal')),'ordinal lock and ingestion guard are internal (no API role can call them)');

select ok((select count(*)=6 and bool_and(not has_function_privilege('service_role',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE') and not has_function_privilege('authenticated',p.oid,'EXECUTE') and not has_function_privilege('public',p.oid,'EXECUTE')) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='offline_pos_private' and p.proname in ('forbid_immutable_mutation','clamp_offline_grant_lease','adjudicate_intent','adjudicate_inventory_intent','intent_policy_int','consume_admin_assertion')),'trigger helpers (immutability, lease clamp), internal adjudication handlers and the admin assertion check are not externally executable (not even by service_role)');
select ok((select count(*)=5 from pg_catalog.pg_constraint where conname in ('offline_grants_device_fk','offline_grants_register_branch_fk','offline_grants_location_fk','offline_grants_operator_fk','offline_sale_ingestions_credential_fk')),'tenant-safe composite foreign keys protect grant and ingestion bindings');
select ok((select pg_catalog.pg_get_constraintdef(oid) like '%needs_reconciliation%' and pg_catalog.pg_get_constraintdef(oid) not like '%pending_review%' from pg_catalog.pg_constraint where conname='offline_operation_intents_disposition'),'new offline intents must carry a final machine disposition; no pending/approval state exists');
select * from finish();
rollback;
